with open(os.environ['GALAXY_API_KEY_FILE']) as fh: key=fh.read().strip()
history='bbd44e69cb8906b53df094301e42e406'
tool='toolshed.g2.bx.psu.edu/repos/iuc/ncbi_datasets/datasets_download_gene/18.33.1+galaxy0'
for taxon in ['Indri indri','Semnopithecus johnii','Homo sapiens']:
    inputs={
      'query': {'subcommand': {
        'download_by': 'symbol',
        'text_or_file': {'text_or_file': 'text', 'accession': 'SHH'},
        'ortholog': '',
        'taxon': taxon
      }},
      'filters': {'fasta_filter_cond': {'fasta_filter_select': ''}},
      'file_choices': {
        'kingdom_cond': {
          'kingdom_sel': 'gene',
          'report_columns': ['common-name','description','gene-id','gene-type','symbol','tax-id','tax-name','transcript-count','protein-count','ensembl-geneids','annotation-assembly-accession','annotation-assembly-name','annotation-release-date','annotation-release-name'],
          'include': ['protein','rna','cds','5p-utr','product-report']
        },
        'decompress': True
      }
    }
    payload={'history_id':history,'tool_id':tool,'inputs':inputs,'input_format':'21.01'}
    req=urllib.request.Request(f'{base}/api/tools', data=json.dumps(payload).encode(), headers={'x-api-key':key,'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(req) as r: data=json.load(r)
        print(taxon, json.dumps({'jobs':[j.get('id') for j in data.get('jobs',[])], 'outputs':{o.get('output_name'):o.get('id') for o in data.get('outputs',[])}}, sort_keys=True))
    except urllib.error.HTTPError as e:
        print(taxon, 'HTTP', e.code, e.read().decode('utf-8','replace')[:1000])
PY"

